code='''def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Find the repeated non-background color bar (the color sequence).
    from collections import Counter
    counts=Counter(v for row in g for v in row if v)
    shape_color=1
    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==shape_color]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    shape={(r-r0,c-c0) for r,c in pts}
    # The sequence is a repeated contiguous colored line/rectangle distinct from shape.
    other=[v for v,n in counts.items() if v!=shape_color]
    # Find largest rectangular uniform component and read its varying-axis colors.
    comps=[]; seen=set()
    for r in range(h):
      for c in range(w):
       v=g[r][c]
       if not v or v==shape_color or (r,c) in seen: continue
       stack=[(r,c)]; seen.add((r,c)); comp=[]
       while stack:
        a,b=stack.pop(); comp.append((a,b))
        for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
         if 0<=x<h and 0<=y<w and g[x][y]==v and (x,y) not in seen: seen.add((x,y)); stack.append((x,y))
       comps.append((v,comp))
    # Identify sequence as a same-color rectangle, often multiple adjacent columns/rows.
    # Each distinct color strip has identical repeated dimension; read across it.
    colors=sorted(set(other), key=lambda v:min((r,c) for r in range(h) for c in range(w) if g[r][c]==v))
    # Axis determined by the aligned sequence rectangle: group by rows/columns, choose axis with more distinct colors.
    # In these tasks the bar is either vertical stack of colors or horizontal sequence repeated.
    rowvals=[]; colvals=[]
    for r in range(h):
      vals=[g[r][c] for c in range(w) if g[r][c] not in (0,shape_color)]
      if vals: rowvals.append((r, vals))
    for c in range(w):
      vals=[g[r][c] for r in range(h) if g[r][c] not in (0,shape_color)]
      if vals: colvals.append((c, vals))
    if len(rowvals)>1 and len(set(v for _,vs in rowvals for v in vs))>=len(colors):
      seq=[]
      for r,vs in rowvals:
       for v in vs:
        if not seq or seq[-1]!=v: seq.append(v)
      # Horizontal bar columns: distinct colors in ordered columns.
      if len(seq)>len(colors): seq=list(dict.fromkeys(g[rowvals[0][0]][c] for c in range(w) if g[rowvals[0][0]][c] not in (0,shape_color)))
    else:
      # Determine order by first occurrence along the bar's long axis.
      if rowvals and len(rowvals)>1:
       seq=[]
       for r,_ in rowvals:
        for c in range(w):
         v=g[r][c]
         if v and v!=shape_color and (not seq or seq[-1]!=v): seq.append(v)
       seq=list(dict.fromkeys(seq))
      else: seq=[]
    seq=list(dict.fromkeys(seq))
    # Prefer horizontal repeated bar: colors are read left-to-right from a row.
    barrows=[r for r in range(h) if any(g[r][c] not in (0,shape_color) for c in range(w))]
    barcols=[c for c in range(w) if any(g[r][c] not in (0,shape_color) for r in range(h))]
    if len(barcols)>1:
      br=barrows[0]
      horiz=[g[br][c] for c in barcols if g[br][c] not in (0,shape_color)]
      if len(set(horiz))>1: seq=list(dict.fromkeys(horiz))
    if not seq: seq=colors
    if shape_color not in seq: seq.insert(len(seq)//2,shape_color)
    k=seq.index(shape_color); out=[[0]*w for _ in range(h)]
    for i,v in enumerate(seq):
      top=r0+(i-k)*(r1-r0+1)
      for dr,dc in shape:
       rr,cc=top+dr,c0+dc
       if 0<=rr<h and 0<=cc<w: out[rr][cc]=v
    return out
